            <input type="text" maxlength="1" class="code-box" inputmode="numeric">
            <input type="text" maxlength="1" class="code-box" inputmode="numeric">
            <input type="text" maxlength="1" class="code-box" inputmode="numeric">
            <input type="text" maxlength="1" class="code-box" inputmode="numeric">
        </div>
        <div class="resend-container">
            <span class="resend-text">إعادة الإرسال خلال <strong id="countdown">0:45</strong></span>
        </div>
        <button class="verify-btn" id="verifyBtn">تحقق</button>
    </div>

    <script>
        const inputs = document.querySelectorAll('.code-box');
        const countdownEl = document.getElementById('countdown');
        const verifyBtn = document.getElementById('verifyBtn');

        // Auto-focus first input on load
        inputs[0].focus();

        // Handle input navigation
        inputs.forEach((input, index) => {
            input.addEventListener('input', function() {
                // Only allow numbers
                this.value = this.value.replace(/[^0-9]/g, '');

                if (this.value.length === 1 && index < inputs.length - 1) {
                    inputs[index + 1].focus();
                }

                // Enable button if all fields filled
                checkAllFilled();
            });

            input.addEventListener('keydown', function(e) {
                if (e.key === 'Backspace' && index > 0 && !this.value) {
                    inputs[index - 1].focus();
                }
            });
        });

        function checkAllFilled() {
            const allFilled = Array.from(inputs).every(input => input.value.length === 1);
            verifyBtn.disabled = !allFilled;
        }

        // Countdown timer
        let timeLeft = 45;
        const countdownInterval = setInterval(() => {
            const minutes = Math.floor(timeLeft / 60);
            const seconds = timeLeft % 60;
            countdownEl.textContent = `${minutes}:${seconds < 10 ? '0' : ''}${seconds}`;
            timeLeft--;

            if (timeLeft < 0) {
                clearInterval(countdownInterval);
                countdownEl.textContent = 'يمكنك إعادة الإرسال الآن';
                countdownEl.parentElement.innerHTML += ' <button id="resendBtn" style="background:none;border:none;color:#0077b6;font-size:14px;cursor:pointer;">إعادة الإرسال</button>';
            }
        }, 1000);
    </script>
